INSERT INTO jobs (job_id, company_id, title, city, category, salary_min_minor, salary_max_minor, salary_months, experience, education, jd, requirements, tags, status, posted_at) VALUES
  ('job_starridge_infer_001', 'comp_starridge', 'LLM Inference Optimization Engineer', 'Shanghai', 'ai_infra', 3100000, 3600000, 14, 'fresh_grad', 'master', 'Responsible for dynamic batching, KV cache management, and GPU utilization optimization for online inference services.', 'Familiar with C++, Python, CUDA profiling, vLLM or TensorRT-LLM, and able to explain the sources of end-to-end latency.', 'AI Infra,LLM inference,CUDA,vLLM', 'open', '2026-05-03'),
  ('job_matrixcloud_platform_001', 'comp_matrixcloud', 'Inference Platform Engineer', 'Shanghai', 'software_engineering', 3500000, 3800000, 13, 'fresh_grad', 'master', 'Build an enterprise inference platform and undertake private deployment delivery for financial clients, with a potentially long on-site customer support cycle.', 'Familiar with distributed systems, Kubernetes, and model serving; able to accept 12 to 18 consecutive months of client-site work.', 'AI Infra,onsite,platform', 'open', '2026-05-04'),
  ('job_bytelattice_kernel_001', 'comp_bytelattice', 'LLM Runtime Kernel Engineer', 'Beijing', 'ai_infra', 3800000, 4200000, 13, 'fresh_grad', 'master', 'Optimize attention operators, KV cache layouts, the scheduler, and multi-GPU communication paths.', 'Has CUDA/C++ performance analysis experience and can use Nsight to locate kernel and memory bottlenecks.', 'LLM runtime,kernel,CUDA', 'open', '2026-05-05'),
  ('job_qingyan_runtime_001', 'comp_qingyan', 'Runtime Systems Engineer', 'Beijing', 'ai_infra', 2800000, 3200000, 15, 'fresh_grad', 'master', 'Responsible for inference runtime stability, model loading pipelines, and service capacity governance.', 'Familiar with Linux, Python/C++, and online services; compensation includes separately valued stock options.', 'runtime systems,LLM,options', 'open', '2026-05-06'),
  ('job_orbit_scheduler_001', 'comp_orbitserve', 'GPU Scheduler Engineer', 'Beijing', 'ai_infra', 2800000, 3400000, 14, 'fresh_grad', 'master', 'Design multi-tenant GPU queues, preemption strategies, and capacity waterline control to reduce fragmentation and queueing delay.', 'Be proficient in scheduling algorithms, Kubernetes device plugins, and observability, and be able to analyze resource fairness.', 'GPU,scheduler,Kubernetes', 'open', '2026-05-07'),
  ('job_orbit_gateway_002', 'comp_orbitserve', 'Model Gateway Backend Engineer', 'Beijing', 'ai_infra', 2600000, 3200000, 14, 'fresh_grad', 'master', 'Develop routing, rate limiting, circuit breaking, and tenant quota capabilities for the model gateway.', 'Familiar with Go or Rust, microservice governance, and high-concurrency network programming.', 'gateway,backend,serving', 'open', '2026-05-08'),
  ('job_pinevector_engine_001', 'comp_pinevector', 'Vector Search Engine Engineer', 'Shanghai', 'software_engineering', 2900000, 3500000, 14, 'fresh_grad', 'master', 'Optimize vector index building, hot and cold data layouts, and hybrid retrieval execution plans.', 'Familiar with database kernels, ANN algorithms, C++, and performance benchmark design.', 'vector search,database,C++', 'open', '2026-05-09'),
  ('job_pinevector_platform_002', 'comp_pinevector', 'Retrieval Platform Engineer', 'Shanghai', 'software_engineering', 2500000, 3100000, 14, 'fresh_grad', 'master', 'Build a search service platform, index publishing workflows, and query quality monitoring.', 'Familiar with Python/Go, distributed storage, and online fault localization.', 'retrieval,platform,SRE', 'open', '2026-05-10'),
  ('job_silicon_compiler_001', 'comp_siliconriver', 'AI Compiler Engineer', 'Shanghai', 'software_engineering', 3000000, 3800000, 15, 'fresh_grad', 'master', 'Develop graph optimization, operator fusion, and code generation for self-developed accelerators.', 'Familiar with MLIR/LLVM, compiler principles, and deep learning computation graphs.', 'compiler,MLIR,accelerator', 'open', '2026-05-11'),
  ('job_silicon_runtime_002', 'comp_siliconriver', 'Accelerator Runtime Engineer', 'Shanghai', 'ai_infra', 3000000, 3700000, 15, 'fresh_grad', 'master', 'Maintain device runtimes, memory allocators, and asynchronous execution queues.', 'Familiar with C/C++, driver interfaces, concurrent programming, and performance tuning.', 'runtime,accelerator,memory', 'open', '2026-05-03'),
  ('job_northstar_training_001', 'comp_northstar', 'Distributed Training Engineer', 'Beijing', 'software_engineering', 3000000, 3900000, 16, 'fresh_grad', 'master', 'Optimize parallel strategies, communication topology, and fault recovery for large-scale training.', 'Familiar with PyTorch distributed, NCCL, and cluster networking; the role focuses on training rather than inference.', 'training,NCCL,distributed', 'open', '2026-05-04'),
  ('job_northstar_inference_002', 'comp_northstar', 'Cloud Inference Service Engineer', 'Beijing', 'ai_infra', 2900000, 3700000, 16, 'fresh_grad', 'master', 'Build cloud model deployment, elastic scaling, and version canary capabilities.', 'Familiar with container platforms, service mesh, and model inference frameworks.', 'cloud,inference,Kubernetes', 'open', '2026-05-05'),
  ('job_lantern_observe_001', 'comp_lanternai', 'LLM Observability Engineer', 'Shanghai', 'ai_infra', 2600000, 3300000, 14, 'fresh_grad', 'master', 'Establish request tracing, token-level metrics, and cost attribution systems.', 'Familiar with OpenTelemetry, time-series databases, and online service performance diagnosis.', 'observability,LLM,metrics', 'open', '2026-05-06'),
