INSERT INTO jobs (job_id, company_id, title, city, category, salary_min_minor, salary_max_minor, salary_months, experience, education, jd, requirements, tags, status, posted_at) VALUES
  ('job_embermesh_dataplane', 'comp_embermesh', 'High-performance Data Plane Engineer', 'Beijing', 'software_engineering', 3200000, 3900000, 14, '3-5', 'bachelor', 'Optimize the user-space network stack, packet processing pipeline, and NUMA resource allocation; the role is for engineers with work experience.', 'At least three years of C/C++ network development experience, familiar with DPDK, eBPF, and performance counters.', 'network,DPDK,eBPF,experienced', 'open', '2026-02-18'),
  ('job_embermesh_observability', 'comp_embermesh', 'Network Observability Intern', 'Beijing', 'intern', 800000, 1200000, 12, 'intern', 'bachelor', 'Develop traffic sampling, topology visualization, and alert data cleaning scripts; the internship period is no less than four months.', 'On-site four days a week, familiar with Python, SQL, and basic network protocols.', 'intern,observability,network', 'open', '2026-03-22'),
  ('job_embermesh_field', 'comp_embermesh', 'Edge Gateway Support Engineer', 'Chengdu', 'customer_success', 2100000, 2700000, 13, '1-3', 'bachelor', 'Support retail store gateway deployment, remote diagnostics, and version upgrades, covering customers in Southwest China.', 'Able to handle about one week of business trips per month, familiar with Linux network troubleshooting.', 'edge,support,travel', 'closed', '2025-11-09'),
  ('job_harborledger_governance', 'comp_harborledger', 'Data Governance Engineer', 'Shenzhen', 'data_engineering', 2400000, 3100000, 14, '1-3', 'master', 'Build metadata catalogs, field lineage, and data quality rules to serve bank compliance reports.', 'Experience in data warehouse or governance projects, familiar with Spark, SQL, and permission models.', 'governance,metadata,Spark', 'open', '2026-01-16'),
  ('job_harborledger_delivery', 'comp_harborledger', 'Banking Platform Delivery Engineer', 'Shenzhen', 'solution_engineering', 2600000, 3300000, 13, 'fresh_grad', 'bachelor', 'Participate in on-site client environment checks, batch-processing platform deployment, and go-live acceptance; in the first year, mainly serve South China clients.', 'Accept continuous on-site assignment and nighttime change windows, and have a foundation in Java, Linux, and databases.', 'banking,delivery,onsite', 'open', '2026-04-03'),
  ('job_harborledger_audit', 'comp_harborledger', 'Audit Data Analyst', 'Shanghai', 'data_analysis', 1900000, 2400000, 13, 'fresh_grad', 'bachelor', 'Check batch job logs, abnormal transactions, and reporting standards; the role leans toward business audit analysis.', 'Familiar with Excel, SQL, and basic financial terminology; system development experience is not required.', 'audit,SQL,reporting', 'closed', '2025-12-11'),
  ('job_maplearchive_validation', 'comp_maplearchive', 'Storage Validation Intern', 'Hangzhou', 'quality_assurance', 700000, 1000000, 12, 'intern', 'bachelor', 'Construct power outage recovery, media damage, and capacity watermark scenarios, and archive the product test results.', 'Able to intern continuously for five months, understands file systems, and can write Python test scripts.', 'storage,testing,intern', 'open', '2026-03-07'),
  ('job_maplearchive_build', 'comp_maplearchive', 'Build and Release Engineer', 'Hangzhou', 'devops', 2200000, 2800000, 14, '1-3', 'bachelor', 'Maintain cross-platform builds, artifact signing, and offline upgrade package release workflows.', 'More than one year of CI/CD experience, familiar with CMake, containers, and software supply chain tools.', 'build,release,CI/CD', 'open', '2026-04-26'),
  ('job_maplearchive_support', 'comp_maplearchive', 'Archive Migration Consultant', 'Beijing', 'solution_engineering', 2500000, 3000000, 12, '5-10', 'bachelor', 'Plan the historical data migration between the tape library and object storage, and take responsibility for capacity assessment and downtime window design.', 'More than five years of enterprise storage experience, able to serve government and enterprise clients long term.', 'archive,migration,consulting', 'closed', '2025-10-28');
